pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address nonOwner, address owner, uint256 reenterAmount) public {
        vm.assume(amount > 0 && amount <= address(c).balance);
        vm.assume(reenterAmount > 0 && reenterAmount <= amount);
        vm.assume(nonOwner != address(0) && nonOwner != owner);
        vm.assume(owner != address(0) && owner != address(c) && owner != address(this));
        vm.assume(nonOwner != address(c) && nonOwner != address(this));

        // Fund the contract
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool s,) = address(c).call{value: amount}("");
        require(s);

        // Deploy adversarial re-entrant callee that calls withdrawAll back into c
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Non-owner attempts sendMoney which should fail under correct access control
        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);

        uint256 balanceBefore = address(c).balance;

        try c.sendMoney(address(attacker), amount, abi.encodeWithSignature("drain(uint256)", reenterAmount)) {
            // If it doesn't revert, the balance should be unchanged because re-entrant drain would be protected by owner check
            // Correct: onlyOwner on withdrawAll prevents re-entrant drain, so balance remains amount
            // Buggy: non-owner can re-enter and drain
            assertEq(address(c).balance, balanceBefore);
        } catch {
            // Reverts are fine; in correct version, non-owner call reverts, but we only care about non-reverting paths.
            // Do nothing.
        }
    }
}

contract ReentrantAttacker {
    C public target;
    constructor(address _target) { target = C(_target); }
    function drain(uint256) external {
        // Re-enter into withdrawAll, draining funds if access control is broken
        target.withdrawAll();
    }
    fallback() external payable {}
}

