pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 depositAmount, uint64 extraAmount) public {
        // Ensure we have a nonzero balance to make the invariant meaningful
        vm.assume(depositAmount > 0);
        // extraAmount is just another fuzzed value that may be sent, but we bound it to avoid overflow
        bound(depositAmount, 1, type(uint64).max);
        bound(extraAmount, 0, type(uint64).max);

        // Fund the contract by sending ether directly (fallback depositsCount++)
        address owner = c.owner();
        vm.deal(owner, uint256(depositAmount) + uint256(extraAmount));
        vm.prank(owner);
        // Send Ether to trigger fallback
        (bool success, ) = address(c).call{value: depositAmount}("");
        require(success, "deposit failed");

        // Possibly send more to vary balance further; the fuzzer can also make extraAmount 0
        if (extraAmount > 0) {
            vm.prank(owner);
            (bool success2, ) = address(c).call{value: extraAmount}("");
            require(success2, "extra deposit failed");
        }

        uint256 balanceBefore = address(c).balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // Invariant: withdrawAll must strictly reduce balance when balance > 0.
        // The correct contract sends everything; the bug sends 0, leaving balance unchanged.
        assertTrue(balanceAfter < balanceBefore);
    }
}

