import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _amount, uint256 _seed) public {
        _amount = bound(_amount, 1, 100 ether);
        vm.assume(_seed != 0);

        address payable owner = payable(address(uint160(uint256(keccak256(abi.encodePacked(_seed))))));
        vm.assume(owner != address(0));
        vm.assume(owner != address(this));
        vm.assume(owner != address(c));

        // Set the stored owner (the contract was deployed by this contract, so owner is address(this)).
        // But the withdrawAll function is `onlyOwner`, so we must prank the actual owner to call withdrawAll.
        // Actually, the contract's owner is `address(this)` because `new C()` makes msg.sender owner.
        // The test contract IS the owner. We fund the test contract and call withdrawAll as ourselves.
        // This simulates the owner calling withdrawAll.

        // Fund the contract with Ether
        vm.deal(address(this), _amount);
        (bool sent,) = address(c).call{value: _amount}("");
        require(sent, "fund failed");

        uint256 balBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;

        // Owner calls withdrawAll
        c.withdrawAll();

        uint256 balAfter = address(c).balance;
        uint256 ownerBalAfter = address(this).balance;

        // General rule: owner balance increase == contract balance decrease
        uint256 ownerDelta = ownerBalAfter - ownerBalBefore;
        uint256 contractDelta = balBefore - balAfter;
        assertTrue(ownerDelta == contractDelta);
    }
}

