import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 _value, address _sender) public {
        vm.assume(_value > 0);
        vm.assume(_sender != address(0));
        // Fund the sender
        vm.deal(_sender, _value);
        // Fund the contract so withdraw has something to send
        vm.deal(address(c), _value);
        // The sender must be the owner to pass onlyOwner
        vm.prank(address(c).call(abi.encodeWithSignature("owner()")));
        // Actually, the sender must be the owner. We can't easily force that without prank to the owner.
        // So let's make _sender the owner by having the owner call withdrawAll to send funds to _sender, then _sender becomes owner? No.
        // Simplest: have the original owner (msg.sender during setUp) be the one who calls withdraw. Since setUp() msg.sender is this test contract,
        // owner is address(this). So we can use vm.prank(address(this)) to simulate the owner.
        // But we also want to fuzz _value. So let _sender just be the owner.
        // To keep the fuzzer parameter meaningful, we can assume _sender == owner, or just prank the owner.
        // The original spec says "after a call to withdraw(...) completes" — the sender is implicitly the owner due to onlyOwner.
        // We'll just use the test contract itself as the owner (setUp sender) and ignore _sender or bound it to address(this).
        vm.assume(_sender == address(this));
        uint256 balBefore = address(c).balance;
        vm.prank(_sender);
        c.withdraw(_value);
        uint256 balAfter = address(c).balance;
        assertTrue(balBefore - balAfter == _value);
    }
}

